import{_ as p,a0 as o,w as s,s as a,ao as u,I as n,a1 as r,A as l,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用 | LCTT x X-CMD","titleTemplate":false,"description":"Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150610 Tickr Is An Open-Source RSS News Ticker for Linux Desktops","title":"Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用","tag":"201508","desc":""},"relativePath":"201508/20150610 Tickr Is An Open-Source RSS News Ticker for Linux Desktops.md","filePath":"[post].md"}'),k={name:"201508/20150610 Tickr Is An Open-Source RSS News Ticker for Linux Desktops.md"};function d(S,t,T,c,m,x){const e=o("Link");return s(),a("div",null,[t[14]||(t[14]=u('<h1 id="tickr-一個開源的-linux-桌面-rss-新聞速遞應用" tabindex="-1">Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用 <a class="header-anchor" href="#tickr-一個開源的-linux-桌面-rss-新聞速遞應用" aria-label="Permalink to “Tickr：一個開源的 Linux 桌面 RSS 新聞速遞應用”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/rss-tickr.jpg" alt=""></p><p><strong>最新的！最新的！閲讀關於它的一切！</strong></p><p>好了，我們今天要推薦的應用程序可不是舊式報紙的二進制版本——它會以一種漂亮的方式將最新的新聞推送到你的桌面上。</p><p>Tickr 是一個基於 GTK 的 Linux 桌面新聞速遞應用，能夠以橫條方式滾動顯示最新頭條新聞以及你最愛的RSS資訊文章標題，當然你可以放置在你桌面的任何地方。</p><p>請叫我 Joey Calamezzo；我把它放在底部，就像電視新聞台的滾動字幕一樣。 （LCTT 譯註： Joan Callamezzo 是 Pawnee Today 的主持人，一位 Pawnee 的本地新聞/脱口秀主持人。而本文作者是 Joey。）</p><p>“到你了，副標題”。</p><h3 id="rss-還記得嗎" tabindex="-1">RSS -還記得嗎？ <a class="header-anchor" href="#rss-還記得嗎" aria-label="Permalink to “RSS -還記得嗎？”">​</a></h3><p>“謝謝，這段結束了。”</p><p>在一個充斥着推送通知、社交媒體、標題黨，以及哄騙人們點擊的清單體的時代，RSS看起來有一點過時了。</p><p>對我來説呢？恩，RSS是名副其實的真正簡單的聚合（RSS ： Really Simple Syndication）。這是將消息通知給我的最簡單、最易於管理的方式。我可以在我願意的時候，管理和閲讀一些東西；沒必要匆忙的去看，以防這條微博消失在信息流中，或者推送通知消失。</p><p>tickr的美在於它的實用性。你可以不斷地有新聞滾動在屏幕的底部，然後不時地瞥一眼。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/tickr-close-up-750x58.jpg" alt=""></p><p>你不會有“閲讀”或“標記所有為已讀”的壓力。當你看到一些你想讀的東西，你只需點擊它，將它在Web瀏覽器中打開。</p><h3 id="開始設置" tabindex="-1">開始設置 <a class="header-anchor" href="#開始設置" aria-label="Permalink to “開始設置”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/tickr-rss-settings.jpg" alt=""></p><p>儘管雖然tickr可以從Ubuntu軟件中心安裝，然而它已經很久沒有更新了。當你打開笨拙的不直觀的控制面板的時候，沒有什麼能夠比這更讓人感覺被遺棄的了。</p><p>要打開它：</p><ol><li>右鍵單擊tickr條</li><li>轉至編輯&gt;首選項</li><li>調整各種設置</li></ol><p>選項和設置行的後面，有些似乎是容易理解的。但是詳細瞭解這些你才能夠掌握一切，包括：</p><ul><li>設置滾動速度</li><li>選擇鼠標經過時的行為</li><li>資訊更新頻率</li><li>字體，包括字體大小和顏色</li><li>消息分隔符（“delineator”）</li><li>tickr在屏幕上的位置</li><li>tickr條的顏色和不透明度</li><li>選擇每種資訊顯示多少文章</li></ul><p>有個值得一提的“怪癖”是，當你點擊“應用”按鈕，只會更新tickr的屏幕預覽。當您退出“首選項”窗口時，請單擊“確定”。</p><p>想要得到完美的顯示效果， 你需要一點點調整，特別是在 Unity 上。</p><p>按下“全寬按鈕”，能夠讓應用程序自動檢測你的屏幕寬度。默認情況下，當放置在頂部或底部時，會留下25像素的間距（應用程序以前是在GNOME2.x桌面上創建的）。只需添加額外的25像素到輸入框，來彌補這個問題。</p><p>其他可供選擇的選項包括：選擇文章在哪個瀏覽器打開；tickr是否以一個常規的窗口出現；是否顯示一個時鐘；以及應用程序多久檢查一次文章資訊。</p><h4 id="添加資訊" tabindex="-1">添加資訊 <a class="header-anchor" href="#添加資訊" aria-label="Permalink to “添加資訊”">​</a></h4><p>tickr自帶的有超過30種不同的資訊列表，從技術Blog到主流新聞服務。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/feed-picker-750x398.jpg" alt=""></p><p>你可以選擇很多你想在屏幕上顯示的新聞提要。如果你想添加自己的資訊，你可以：—</p><ol><li>右鍵單擊tickr條</li><li>轉至文件&gt;打開資訊</li><li>輸入資訊網址</li><li>點擊“添加/更新”按鈕</li><li>單擊“確定”（選擇）</li></ol><p>如果想設置每個資訊在ticker中顯示多少條文章，可以去另一個首選項窗口修改“每個資訊最大讀取N條文章”</p><h3 id="在ubuntu-14-04-lts或更高版本上安裝tickr" tabindex="-1">在Ubuntu 14.04 LTS或更高版本上安裝Tickr <a class="header-anchor" href="#在ubuntu-14-04-lts或更高版本上安裝tickr" aria-label="Permalink to “在Ubuntu 14.04 LTS或更高版本上安裝Tickr”">​</a></h3><p>這就是 Tickr，它不會改變世界，但是它能讓你知道世界上發生了什麼。</p><p>在Ubuntu 14.04 LTS或更高版本中安裝，點擊下面的按鈕轉到Ubuntu軟件中心。</p>',34)),n("ul",null,[n("li",null,[r(e,{href:"apt://tickr"},{default:l(()=>[...t[0]||(t[0]=[i("點擊此處進入Ubuntu軟件中心安裝tickr",-1)])]),_:1})])]),t[15]||(t[15]=n("hr",null,null,-1)),n("p",null,[t[2]||(t[2]=i("via: ",-1)),r(e,{href:"http://www.omgubuntu.co.uk/2015/06/tickr-open-source-desktop-rss-news-ticker"},{default:l(()=>[...t[1]||(t[1]=[i("http://www.omgubuntu.co.uk/2015/06/tickr-open-source-desktop-rss-news-ticker",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=i("作者：",-1)),r(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:l(()=>[...t[3]||(t[3]=[i("Joey-Elijah Sneddon",-1)])]),_:1}),t[7]||(t[7]=i(" 譯者：",-1)),r(e,{href:"https://github.com/xiaoyu33"},{default:l(()=>[...t[4]||(t[4]=[i("xiaoyu33",-1)])]),_:1}),t[8]||(t[8]=i(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=i("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[9]||(t[9]=[i("LCTT",-1)])]),_:1}),t[12]||(t[12]=i(" 原創翻譯，",-1)),r(e,{href:"https://linux.cn/"},{default:l(()=>[...t[10]||(t[10]=[i("Linux中國",-1)])]),_:1}),t[13]||(t[13]=i(" 榮譽推出",-1))])])}const b=p(k,[["render",d]]);export{g as __pageData,b as default};
